/**
 * Day 19 — Binary Tree Part-III. Original statements + reference solutions for
 * the in-portal Striver SDE Sheet. Expected outputs are generated by verify.
 */

function buildTree(serial) {
  const tokens = serial.trim().split(/\s+/);
  if (!tokens.length || tokens[0] === 'null') return null;
  const root = { val: tokens[0], left: null, right: null };
  const queue = [root];
  let i = 1;
  while (queue.length && i < tokens.length) {
    const node = queue.shift();
    if (i < tokens.length) {
      const t = tokens[i++];
      if (t !== 'null') { node.left = { val: t, left: null, right: null }; queue.push(node.left); }
    }
    if (i < tokens.length) {
      const t = tokens[i++];
      if (t !== 'null') { node.right = { val: t, left: null, right: null }; queue.push(node.right); }
    }
  }
  return root;
}

/** Serialize as level order with 'null' placeholders, trailing nulls trimmed. */
function serialize(root) {
  if (!root) return 'null';
  const out = [];
  const queue = [root];
  while (queue.length) {
    const node = queue.shift();
    if (!node) { out.push('null'); continue; }
    out.push(node.val);
    queue.push(node.left);
    queue.push(node.right);
  }
  while (out.length && out[out.length - 1] === 'null') out.pop();
  return out.join(' ');
}

function construct(preorder, inorder) {
  if (!preorder.length) return null;
  const rootVal = preorder[0];
  const idx = inorder.indexOf(rootVal);
  const root = { val: rootVal, left: null, right: null };
  root.left = construct(preorder.slice(1, 1 + idx), inorder.slice(0, idx));
  root.right = construct(preorder.slice(1 + idx), inorder.slice(idx + 1));
  return root;
}

const TREES = [
  '1 2 3 null 4 5 6',
  '1',
  '1 2 null 3',
  '1 2 3 4 5 6 7',
  '1 2 null 3 null 4 null 5',
  '5 3 8 2 4 7 9',
  '1 2 3 4 5 6 7',
  '7 6 5 4 3 null 2',
  '1 2 3 null null 4 5',
  '4 2 6 1 3 5 7',
  '8 3 10 1 6 null 14 null null 4 7 13',
  '10 5 15 3 7 12 20',
  '2 null 3 null 4 null 5',
  '-1 -2 -3 null null 0 1',
  '9 8 7 6 null 5 4',
];

export default {
  section: 'Day 19: Binary Tree Part-III',
  problems: [
    {
      slug: 'binary-tree-maximum-path-sum',
      title: 'Binary Tree Maximum Path Sum',
      difficulty: 'Hard',
      topic: 'Binary Tree',
      description: `A **path** in a binary tree is a sequence of nodes where each adjacent pair is connected by an edge, and no node appears twice (it does not need to start or end at the root).

Print the maximum path sum (the sum of node values along the best path). Node values may be negative, and the path must contain at least one node.

Input format: one line with the tree in level order, using \`null\` for missing children.

{{EXAMPLES}}`,
      constraints: '1 <= number of nodes <= 10^4\n-1000 <= node value <= 1000',
      inputs: TREES,
      solve(input) {
        const root = buildTree(input);
        let best = -Infinity;
        const gain = node => {
          if (!node) return 0;
          const left = Math.max(0, gain(node.left));
          const right = Math.max(0, gain(node.right));
          best = Math.max(best, node.val + left + right);
          return node.val + Math.max(left, right);
        };
        gain(root);
        return String(best);
      },
    },
    {
      slug: 'construct-from-preorder-inorder',
      title: 'Construct Binary Tree from Preorder and Inorder Traversal',
      difficulty: 'Medium',
      topic: 'Binary Tree',
      description: `Given the **preorder** and **inorder** traversals of a binary tree with distinct values, rebuild the tree.

Input format: first line the preorder sequence, second line the inorder sequence (values separated by single spaces).

Print the rebuilt tree as a **level-order** list using \`null\` for missing children, with trailing nulls omitted.

{{EXAMPLES}}`,
      constraints: '1 <= number of nodes <= 1000\nAll values distinct and valid traversals of the same tree',
      inputs: [
        '3 9 20 15 7\n9 3 15 20 7',
        '1\n1',
        '1 2\n2 1',
        '1 2 3\n2 1 3',
        '4 2 1 3 6 5 7\n1 2 3 4 5 6 7',
        '5 3 1 2 4\n1 2 3 4 5',
        '1 2 4 5 3 6 7\n4 2 5 1 6 3 7',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const preorder = lines[0].split(/\s+/);
        const inorder = lines[1].split(/\s+/);
        return serialize(construct(preorder, inorder));
      },
    },
    {
      slug: 'construct-from-inorder-postorder',
      title: 'Construct Binary Tree from Inorder and Postorder Traversal',
      difficulty: 'Medium',
      topic: 'Binary Tree',
      description: `Given the **inorder** and **postorder** traversals of a binary tree with distinct values, rebuild the tree.

Input format: first line the inorder sequence, second line the postorder sequence (values separated by single spaces).

Print the rebuilt tree as a **level-order** list using \`null\` for missing children, with trailing nulls omitted.

{{EXAMPLES}}`,
      constraints: '1 <= number of nodes <= 1000\nAll values distinct and valid traversals of the same tree',
      inputs: [
        '9 3 15 20 7\n9 15 7 20 3',
        '1\n1',
        '2 1\n2 1',
        '1 2 3\n2 3 1',
        '1 2 3 4 5 6 7\n4 5 2 6 7 3 1',
        '1 2 3 4 5\n2 4 5 3 1',
        '4 2 1 3\n4 2 3 1',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const inorder = lines[0].split(/\s+/);
        const postorder = lines[1].split(/\s+/);
        const build = (ino, post) => {
          if (!post.length) return null;
          const rootVal = post[post.length - 1];
          const idx = ino.indexOf(rootVal);
          const root = { val: rootVal, left: null, right: null };
          root.left = build(ino.slice(0, idx), post.slice(0, idx));
          root.right = build(ino.slice(idx + 1), post.slice(idx, post.length - 1));
          return root;
        };
        return serialize(build(inorder, postorder));
      },
    },
    {
      slug: 'symmetric-binary-tree',
      title: 'Symmetric Binary Tree (mirror of itself)',
      difficulty: 'Easy',
      topic: 'Binary Tree',
      description: `A tree is **symmetric** if the left subtree is the exact mirror image of the right subtree.

Print \`YES\` if the tree is symmetric, otherwise \`NO\`.

Input format: one line with the tree in level order, using \`null\` for missing children.

{{EXAMPLES}}`,
      constraints: '1 <= number of nodes <= 10^4\nNode values are distinct',
      inputs: TREES,
      solve(input) {
        const root = buildTree(input);
        const mirror = (a, b) => {
          if (!a && !b) return true;
          if (!a || !b) return false;
          return a.val === b.val && mirror(a.left, b.right) && mirror(a.right, b.left);
        };
        return mirror(root, root) ? 'YES' : 'NO';
      },
    },
    {
      slug: 'flatten-binary-tree-linked-list',
      title: 'Flatten Binary Tree to Linked List (preorder order)',
      difficulty: 'Medium',
      topic: 'Binary Tree',
      description: `Flatten a binary tree into a "linked list" using only \`right\` pointers: every node's \`left\` becomes \`null\` and its \`right\` points to the node that comes **next in preorder** traversal.

Print the preorder sequence of the flattened tree (which is exactly the order of the resulting chain), values separated by single spaces.

Input format: one line with the tree in level order, using \`null\` for missing children.

{{EXAMPLES}}`,
      constraints: '1 <= number of nodes <= 10^4\nNode values are distinct',
      inputs: TREES,
      solve(input) {
        const root = buildTree(input);
        const out = [];
        const preorder = node => {
          if (!node) return;
          out.push(node.val);
          preorder(node.left);
          preorder(node.right);
        };
        preorder(root);
        return out.join(' ');
      },
    },
    {
      slug: 'children-sum-property',
      title: 'Check Children Sum Property',
      difficulty: 'Medium',
      topic: 'Binary Tree',
      description: `The **children sum property** holds when every node's value equals the sum of its children's values — a missing (null) child counts as \`0\`, and leaf nodes always satisfy the property.

Print \`YES\` if the tree satisfies the property, otherwise \`NO\`.

Input format: one line with the tree in level order, using \`null\` for missing children.

{{EXAMPLES}}`,
      constraints: '1 <= number of nodes <= 10^4\n-10^4 <= node value <= 10^4',
      inputs: [
        '1 2 3\n1 2 3',
        '10 4 6 1 3 3 3',
        '1 2 4\n1 2 4',
        '10 4 6 1 3 3 100',
        '5\n5',
        '2 1 1\n1 1 1',
        '7 3 4 1 2 2 2',
      ],
      solve(input) {
        const root = buildTree(input);
        let ok = true;
        const check = node => {
          if (!node) return;
          const left = node.left ? node.left.val : 0;
          const right = node.right ? node.right.val : 0;
          if (node.left || node.right) {
            if (Number(node.val) !== left + right) ok = false;
          }
          check(node.left);
          check(node.right);
        };
        check(root);
        return ok ? 'YES' : 'NO';
      },
    },
  ],
};
